"""Exceptions for the projects service."""

from qbraid_core.exceptions import HttpStatusMixin, QbraidException


class ProjectServiceRequestError(HttpStatusMixin, QbraidException):
    """Raised when a request to the projects API fails."""


class ProjectNotFoundError(HttpStatusMixin, QbraidException):
    """Raised when a project cannot be found."""


class ProjectCloneError(QbraidException):
    """Raised when cloning a project's GitHub repository fails."""


class ProjectInstallError(QbraidException):
    """Raised when project installation (clone + env install) fails."""
